import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";

import { useAppContext } from "../context/AppContext";
import api from "../services/api";

// ✅ SAFE TOKEN PARSE
const getRoleFromToken = (token) => {
  try {
    const payload = JSON.parse(atob(token.split(".")[1]));
    return payload?.role || null;
  } catch {
    return null;
  }
};

const Login = () => {
  const navigate = useNavigate();
  const { preloadAfterLogin } = useAppContext();

  const [formData, setFormData] = useState({
    username: "",
    password: "",
  });

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // ✅ AUTO REDIRECT IF ALREADY LOGGED IN
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      const role = getRoleFromToken(token);
      if (role === "admin") navigate("/admin", { replace: true });
      if (role === "client") navigate("/client", { replace: true });
    }
  }, [navigate]);

  const handleChange = (e) => {
    setFormData((prev) => ({
      ...prev,
      [e.target.name]: e.target.value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const res = await api.post("/auth/login", formData);

      const token = res.data.access_token;
      const role = getRoleFromToken(token);

      const userData = res.data.user || {
        username: formData.username,
        role,
      };

      // ✅ SAVE DATA
      localStorage.setItem("token", token);
      localStorage.setItem("user", JSON.stringify(userData));

      // ✅ INSTANT NAVIGATION (FAST UX)
      if (role === "admin") {
        navigate("/admin");
      } else {
        navigate("/client");
      }

      // ✅ BACKGROUND PREFETCH (NON-BLOCKING)
      setTimeout(() => {
        preloadAfterLogin(role);
      }, 0);
    } catch (err) {
      console.log("LOGIN ERROR:", err);

      const msg =
        err.response?.data?.detail ||
        err.message ||
        "Server not reachable";

      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-shell">
      <div className="auth-hero">
        <p className="eyebrow">College Resource Booking</p>
        <h1>Book labs, halls & resources instantly</h1>
        <p>Fast, simple and optimized booking system.</p>
      </div>

      <div className="auth-card">
        <h2>Sign In</h2>
        <p>Use your account credentials to continue.</p>

        <form onSubmit={handleSubmit} className="auth-form">
          <label>
            <span>Username</span>
            <input
              type="text"
              name="username"
              value={formData.username}
              onChange={handleChange}
              required
            />
          </label>

          <label>
            <span>Password</span>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </label>

          {/* ✅ ERROR UI */}
          {error && <div className="alert error">{error}</div>}

          <button
            type="submit"
            className="primary-button auth-button"
            disabled={loading}
          >
            {loading ? "Logging in..." : "Login"}
          </button>
        </form>

        <p className="auth-link">
          New user? <Link to="/register">Create an account</Link>
        </p>
      </div>
    </div>
  );
};

export default Login;
